//  Availability =   Run Time /Planned Production Time
if({[.]SecondsElapsed} = 0, 1,
{[.]RunSeconds} /{[.]SecondsElapsed})

//seconds between interval starting time and now
//zero if the start time is now, or this instance is disabled
if({[.]StartTime} = None || {[.]Enabled}  = 0 ,0,
min(secondsBetween({[.]StartTime},now(250)),{[.]Duration})
)

//  Utilization = Planned Production Time / All Time
if({[.]SecondsElapsed} = 0, 1,
({[.]SecondsElapsed}  - {[.]IdleSeconds}) /{[.]SecondsElapsed})
